def comps_by_colors(grid, colors):
 R,C=len(grid),len(grid[0]);seen=set();out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c] in colors and (r,c) not in seen:
    q=deque([(r,c)]);seen.add((r,c));comp=[]
    while q:
     p=q.popleft();comp.append(p)
     for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
      n=(p[0]+dr,p[1]+dc)
      if 0<=n[0]<R and 0<=n[1]<C and grid[n[0]][n[1]] in colors and n not in seen:
       seen.add(n);q.append(n)
    out.append(comp)
 return out
